/**
 * GetGit — сервер (Cloudflare Worker + база D1).
 * Один файл: приложение, вход (GitHub / Apple / почта), база, оплата Rolly Pay (СБП), пересказы проектов, админка.
 * Настройка с телефона описана в README.md. Секреты хранятся только в настройках Worker, не в коде.
 */
const SCHEMA = ["CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, email TEXT UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, name TEXT, avatar TEXT, github_id TEXT UNIQUE, github_login TEXT, apple_sub TEXT UNIQUE, pass_hash TEXT, pass_salt TEXT, plan_until INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL DEFAULT 0 )", "CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires INTEGER NOT NULL, created_at INTEGER NOT NULL )", "CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id)", "CREATE TABLE IF NOT EXISTS login_codes ( email TEXT PRIMARY KEY, code_hash TEXT NOT NULL, expires INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 )", "CREATE TABLE IF NOT EXISTS oauth_states ( state TEXT PRIMARY KEY, kind TEXT NOT NULL, nonce TEXT, created_at INTEGER NOT NULL )", "CREATE TABLE IF NOT EXISTS saves ( user_id TEXT NOT NULL, repo TEXT NOT NULL, data TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (user_id, repo) )", "CREATE TABLE IF NOT EXISTS views ( repo TEXT NOT NULL, viewer TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (repo, viewer) )", "CREATE INDEX IF NOT EXISTS idx_views_repo ON views(repo)", "CREATE TABLE IF NOT EXISTS summaries ( repo TEXT PRIMARY KEY, text TEXT NOT NULL, ai INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL )", "CREATE TABLE IF NOT EXISTS usage ( user_key TEXT NOT NULL, day TEXT NOT NULL, kind TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_key, day, kind) )", "CREATE TABLE IF NOT EXISTS payments ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, plan TEXT NOT NULL, method TEXT NOT NULL, amount TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'RUB', provider TEXT NOT NULL DEFAULT 'rollypay', provider_id TEXT, pay_url TEXT, status TEXT NOT NULL DEFAULT 'created', test INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, paid_at INTEGER )", "CREATE INDEX IF NOT EXISTS idx_pay_user ON payments(user_id)", "CREATE INDEX IF NOT EXISTS idx_pay_provider ON payments(provider_id)", "CREATE TABLE IF NOT EXISTS tr ( repo TEXT NOT NULL, lang TEXT NOT NULL, text TEXT NOT NULL, ai INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, PRIMARY KEY (repo, lang) )", "CREATE TABLE IF NOT EXISTS refs ( code TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL )", "CREATE TABLE IF NOT EXISTS ref_uses ( invitee TEXT PRIMARY KEY, inviter TEXT NOT NULL, ts INTEGER NOT NULL, rewarded INTEGER NOT NULL DEFAULT 0 )", "CREATE INDEX IF NOT EXISTS idx_ref_inviter ON ref_uses(inviter)", "CREATE TABLE IF NOT EXISTS promos ( code TEXT PRIMARY KEY, kind TEXT NOT NULL, value INTEGER NOT NULL, max_uses INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL )", "CREATE TABLE IF NOT EXISTS promo_uses ( code TEXT NOT NULL, user_id TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (code, user_id) )", "CREATE TABLE IF NOT EXISTS pay_extra ( pay_id TEXT PRIMARY KEY, promo TEXT, ad_id TEXT )", "CREATE TABLE IF NOT EXISTS ads ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL, repo TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', days INTEGER NOT NULL, starts INTEGER NOT NULL DEFAULT 0, ends INTEGER NOT NULL DEFAULT 0, imp INTEGER NOT NULL DEFAULT 0, clk INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL )", "CREATE INDEX IF NOT EXISTS idx_ads_status ON ads(status, ends)", "CREATE INDEX IF NOT EXISTS idx_ads_user ON ads(user_id)"];
